            // blob from FUZZ_PARAM_STR() is guaranteed >=1 byte, so copy_len>=1
            for (size_t j = 0; j < copy_len; ++j) {
                cert_storage[i][j] = (unsigned char)blob[j];
            }
            cert_ptrs[i] = cert_storage[i];
            cert_lens[i] = (int)copy_len; // cert_len[i] >= 0 as required
