import random
import string
from typing import List

def _rand_bool(r: random.Random, p: float = 0.5) -> bool:
    return r.random() < p

# Build a realistic options string for vcard_emul_options and vcard_init params
# Goals:
# - Include a mix of flags, key=value pairs, and lists
# - Cover known emulation types and edge cases
# - Keep <= 4096 bytes, typically far smaller
# - Deterministic given seed

def _choose(r: random.Random, seq: List[str]) -> str:
    return seq[r.randrange(len(seq))]

def _rand_token(r: random.Random) -> str:
    # General token of letters, digits, dash/underscore
    length = r.randint(1, 12)
    alphabet = string.ascii_letters + string.digits + "-_"
    return ''.join(r.choice(alphabet) for _ in range(length))

def _rand_hex(r: random.Random, nbytes: int) -> str:
    return ''.join(r.choice('0123456789abcdef') for _ in range(nbytes * 2))

def _rand_decimal(r: random.Random, minv: int, maxv: int) -> str:
    return str(r.randint(minv, maxv))

def _maybe_quote(r: random.Random, s: str) -> str:
    if _rand_bool(r, 0.2):
        # choose single or double quotes
        q = '"' if _rand_bool(r, 0.5) else "'"
        return q + s + q
    return s

def _kv(r: random.Random) -> str:
    # Key-value pairs typical for emulator options
    keys = [
        'type', 'emul', 'mode', 'reader', 'name',
        'serial', 'atr', 'aid', 'pin', 'pinlen',
        'compat', 'verbose', 'debug', 'channel', 'le', 'lc',
        'rsa_bits', 'timeout', 'retries', 'feature', 'flags'
    ]
    key = _choose(r, keys)
    # value type by key
    if key in ('type', 'emul', 'mode'):
        # Supported types and variants
        vals = ['none', 'NONE', 'cac', 'CAC', 'passthru', 'passthrough', 'PASSTHRU']
        val = _choose(r, vals)
    elif key in ('reader', 'name', 'feature'):
        val = _maybe_quote(r, _rand_token(r))
    elif key in ('serial',):
        # decimal or hex
        if _rand_bool(r):
            val = _rand_decimal(r, 0, 10**10)
        else:
            # hex bytes
            bytelen = r.randint(4, 16)
            val = '0x' + _rand_hex(r, bytelen)
    elif key in ('atr', 'aid'):
        # ATR/AID as hex bytes (5-19 bytes typical for AID)
        bytelen = r.randint(5, 19)
        val = '0x' + _rand_hex(r, bytelen)
    elif key in ('pin',):
        # PIN as digits, maybe quoted
        pinlen = r.randint(4, 12)
        val = _maybe_quote(r, ''.join(r.choice(string.digits) for _ in range(pinlen)))
    elif key in ('pinlen', 'rsa_bits', 'timeout', 'retries', 'channel', 'le', 'lc'):
        ranges = {
            'pinlen': (0, 16),
            'rsa_bits': (512, 4096),
            'timeout': (0, 600),
            'retries': (0, 15),
            'channel': (0, 19),
            'le': (0, 65535),
            'lc': (0, 65535),
        }
        lo, hi = ranges.get(key, (0, 100))
        val = _rand_decimal(r, lo, hi)
    elif key in ('compat', 'flags'):
        # bitmask in hex or list of named flags
        if _rand_bool(r):
            val = '0x' + _rand_hex(r, r.randint(1, 4))
        else:
            compat_names = [
                'T0', 'T1', 'EXT_LE', 'EXT_LC', 'NO_CHAIN', 'CHAIN', 'LEGACY', 'STRICT'
            ]
            count = r.randint(1, 4)
            parts = r.sample(compat_names, k=count)
            val = _maybe_quote(r, ','.join(parts))
    elif key in ('verbose', 'debug'):
        val = _choose(r, ['0','1','2','3'])
    else:
        val = _rand_token(r)
    return f"{key}={val}"

def _flag(r: random.Random) -> str:
    # Single switches
    flags = [
        '--verbose', '--debug', '--strict', '--relaxed', '--no-sm', '--sm',
        '--allow-extended', '--no-extended', '--chain', '--no-chain'
    ]
    f = _choose(r, flags)
    # some flags can take optional values
    if f in ('--verbose', '--debug') and _rand_bool(r, 0.4):
        f += '=' + _choose(r, ['1','2','3'])
    return f

def _section(r: random.Random) -> str:
    # Produce a section: either flags or comma-separated k=v pairs
    mode = r.randrange(3)
    if mode == 0:
        # flags joined by space
        n = r.randint(1, 4)
        return ' '.join(_flag(r) for _ in range(n))
    elif mode == 1:
        # k=v comma list
        n = r.randint(1, 6)
        return ','.join(_kv(r) for _ in range(n))
    else:
        # mixed
        n1 = r.randint(1, 3)
        n2 = r.randint(1, 3)
        parts = [ _flag(r) for _ in range(n1) ] + [ _kv(r) for _ in range(n2) ]
        r.shuffle(parts)
        return ' '.join(parts)

def _build_options_string(r: random.Random) -> str:
    # Start with an explicit type sometimes
    base_parts = []
    if _rand_bool(r, 0.8):
        type_val = _choose(r, ['cac', 'passthru', 'none', 'CAC', 'PASSTHRU'])
        base_parts.append(f"type={type_val}")
    # Add several sections separated by spaces; some may be quoted
    nsections = r.randint(1, 6)
    for _ in range(nsections):
        base_parts.append(_section(r))
    s = ' '.join(base_parts)
    # Occasionally produce empty to exercise defaults
    if _rand_bool(r, 0.1):
        s = ''
    # Trim to reasonable size (fuzzer stub also trims to 512)
    if len(s) > 500:
        s = s[:500]
    return s

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    s = _build_options_string(r)
    # Return as bytes with a terminating NUL often unnecessary for std::string,
    # but stubs pass c_str(), so ensure proper C-string by relying on internal NUL.
    # We just return the bytes of the string; the harness will write to file or memory.
    data = s.encode('utf-8')
    # Keep under 4096 bytes
    if len(data) > 4096:
        data = data[:4096]
    return data
